import pennylane as qml
import numpy as np
import scipy.optimize as optimize

def compute_observables(params, dev, wires):
    def Jxx(x, y): return x*x + y*y
    def Jzz(x): return params['Delta'] * x*x

    def Hamiltonian(params, dev, wires):
        qml.QubitStateVector(np.ones(wires) / np.sqrt(2), wires)
        return qml.exp_val_ps(dev, qml.Hamiltonian(Jxx, wires=wires, J=params['J']), wires) + qml.exp_val_ps(dev, qml.Hamiltonian(Jzz, wires=wires, J=params['J']), wires)

    def staggered_magnetization(dev, wires):
        sm = 0.0
        for i in range(wires):
            if i % 2 == 0:
                sm += qml.exp_val_ps(dev, qml.PauliZ(wires[i]), wires=[wires[i]])
            else:
                sm -= qml.exp_val_ps(dev, qml.PauliZ(wires[i]), wires=[wires[i]])
        return sm / wires

    def ferromagnetic_order_parameter(dev, wires):
        return np.abs(sum([qml.exp_val_ps(dev, qml.PauliZ(wires[i]), wires=[wires[i]]) for i in range(wires)]) / wires)

    def spin_spin_correlation(dev, wires, r):
        return qml.exp_val_ps(dev, qml.PauliZ(wires[0]) * qml.PauliZ(wires[r]), wires=[wires[0], wires[r]])

    def structure_factor(dev, wires, q):
        N = wires
        S = (1/N) * sum([[q**(i-j) * spin_spin_correlation(dev, wires, abs(i-j)) for i in range(N)] for j in range(N)])
        return S[0] if q == 0 else S[len(S)-1]

    def spin_gap(dev, wires):
        energies, _ = qml.eigvals_minima_and_eigvecs(Hamiltonian, num_ shots=4096, dev=dev, wires=wires)
        return energies[1] - energies[0]

    dev.initialize()
    params['H'] = Hamiltonian(params, dev, wires)

    return {'staggered_magnetization': staggered_magnetization(dev, wires),
            'ferromagnetic_order_parameter': ferromagnetic_order_parameter(dev, wires),
            'spin_spin_correlation_C(0)': spin_spin_correlation(dev, wires, 0),
            'spin_spin_correlation_C(1)': spin_spin_correlation(dev, wires, 1),
            'structure_factor_S(0)': structure_factor(dev, wires, 0),
            'structure_factor_S(pi)': structure_factor(dev, wires, np.pi),
            'spin_gap': spin_gap(dev, wires)}

def objective_function(params, observables):
    dev = qml.device('qutip.cnot-qutip', wires=params['num_spins'])
    return sum([(obs - params['observables'][obs]['true_value']) ** 2 for obs, obs_val in observables.items()])

