                'spin_spin_correlation_C(0)': {'true_value': 1.0},
                'spin_spin_correlation_C(1)': {'true_value': 0.0},
                'structure_factor_S(0)': {'true_value': 1.0},
                'structure_factor_S(pi)': {'true_value': 0.0},
